import{_ as a,a as s,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 05：写 Issue、Commit 与 PR","description":"用可复现的问题描述、简洁的提交信息和可审查的变更说明参与英文开发协作。","frontmatter":{"title":"程序员英语 05：写 Issue、Commit 与 PR","description":"用可复现的问题描述、简洁的提交信息和可审查的变更说明参与英文开发协作。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"用可复现的问题描述、简洁的提交信息和可审查的变更说明参与英文开发协作。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search"},"next":{"text":"程序员英语 06：代码评审与技术说明","link":"/life/english/programmer/review-writing"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search"},"next":{"text":"程序员英语 06：代码评审与技术说明","link":"/life/english/programmer/review-writing"}},"headers":[],"relativePath":"life/english/programmer/issue-pr.md","filePath":"life/english/programmer/issue-pr.md"}'),i={name:"life/english/programmer/issue-pr.md"};function l(p,e,o,r,d,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="程序员英语-05-写-issue、commit-与-pr" tabindex="-1">程序员英语 05：写 Issue、Commit 与 PR <a class="header-anchor" href="#程序员英语-05-写-issue、commit-与-pr" aria-label="Permalink to &quot;程序员英语 05：写 Issue、Commit 与 PR&quot;">​</a></h1><p>Issue 帮助别人理解问题，Commit 记录一次修改，PR 帮助评审者判断改动是否合适。三者可以围绕同一个缺陷，但不必粘贴同一段文字。</p><h2 id="issue-先让问题可复现" tabindex="-1">Issue：先让问题可复现 <a class="header-anchor" href="#issue-先让问题可复现" aria-label="Permalink to &quot;Issue：先让问题可复现&quot;">​</a></h2><p>下面是虚构 CSV 导入器的完整教学案例：约定默认跳过空行；输入为表头、一个空行、一条数据；实际在空行处停止。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Title: Import stops at a blank line in default mode</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Environment: csv-reader 2.4, Linux</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Steps to reproduce:</span></span>
<span class="line"><span>1. Create a UTF-8 file with a header, a blank line, and one data row.</span></span>
<span class="line"><span>2. Import the file with default settings.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Expected: The importer skips the blank line and reads the data row.</span></span>
<span class="line"><span>Actual: The import stops at line 2 with &quot;invalid record&quot;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The same file imports successfully after I remove the blank line.</span></span></code></pre></div><p>标题包含对象、行为与条件，比 <code>Bug report</code> 更容易检索。步骤按顺序编号，预期和实际分开，最后一行是对照实验。版本、系统和结果来自案例设定，实际项目需要换成真实证据。</p><p>若文件内容决定能否复现，就附最小输入，而非只写“使用一个 CSV”。<a href="https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/creating-an-issue" target="_blank" rel="noopener noreferrer">GitHub 创建 Issue 文档</a> 说明了 Issue 与模板的入口；具体项目有模板时，按其字段填写。</p><h2 id="commit-一句话概括行为变化" tabindex="-1">Commit：一句话概括行为变化 <a class="header-anchor" href="#commit-一句话概括行为变化" aria-label="Permalink to &quot;Commit：一句话概括行为变化&quot;">​</a></h2><p>可用动作开头：<code>Skip blank lines before validating CSV records</code>。它告诉读者改了什么，没有夸大成修复所有导入问题。</p><p><code>fix: skip blank lines before record validation</code> 是另一种可能的团队格式；<code>fix:</code> 不是英语语法要求，也不是所有仓库必须使用的前缀。先遵循当前项目的提交约定。</p><p>需要正文时补充为什么：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skip blank lines before validating CSV records</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Blank lines reached the record validator and stopped default imports.</span></span>
<span class="line"><span>Handle them before validation so the importer follows the documented behavior.</span></span></code></pre></div><h2 id="pr-让评审者知道看什么" tabindex="-1">PR：让评审者知道看什么 <a class="header-anchor" href="#pr-让评审者知道看什么" aria-label="Permalink to &quot;PR：让评审者知道看什么&quot;">​</a></h2><p>一份短 PR 描述可以这样写：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Default imports stop when a blank line reaches the record validator.</span></span>
<span class="line"><span>This change skips blank lines before validation and keeps malformed,</span></span>
<span class="line"><span>non-empty records on the existing validation path.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Validation:</span></span>
<span class="line"><span>- Added a regression case with a blank line between two records.</span></span>
<span class="line"><span>- Checked that malformed, non-empty records still fail in strict mode.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Review focus: Please check the distinction between blank and whitespace-only lines.</span></span></code></pre></div><p>这段刻意把边界留给评审：空字符串和只含空格的行是否都该跳过，需要产品定义，不能靠一个 <code>trim()</code> 默默决定。<code>Added</code>、<code>Checked</code> 仅能用于已经完成的验证；计划做的检查写成 <code>Planned validation</code>。</p><h2 id="高频表达与语气" tabindex="-1">高频表达与语气 <a class="header-anchor" href="#高频表达与语气" aria-label="Permalink to &quot;高频表达与语气&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>可以使用的表达</th></tr></thead><tbody><tr><td>说明触发条件</td><td>This occurs when ...</td></tr><tr><td>说明影响</td><td>This prevents users from ...</td></tr><tr><td>说明修改</td><td>This change allows ...</td></tr><tr><td>请求具体评审</td><td>Please check whether ...</td></tr><tr><td>承认验证边界</td><td>I have not tested this on ...</td></tr><tr><td>标记待确认项</td><td>It is unclear whether ...</td></tr></tbody></table><p>避免只有 <code>optimized</code>、<code>improved</code> 或 <code>fixed the bug</code>。这些词没有说明哪个行为发生了变化。</p><h2 id="练习-把标题写具体" tabindex="-1">练习：把标题写具体 <a class="header-anchor" href="#练习-把标题写具体" aria-label="Permalink to &quot;练习：把标题写具体&quot;">​</a></h2><p>已知：虚构编辑器关闭前有未保存内容；选择 Cancel 后窗口仍关闭；期望窗口保持打开。写 Issue 标题、一个预期句和一个 PR 首句。修复尚未测试。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p>标题：<code>Editor closes after Cancel is selected in the unsaved-changes dialog</code>。</p><p>预期：<code>Selecting Cancel should keep the editor open with the unsaved content intact.</code></p><p>PR 首句：<code>This change keeps the editor open when the user cancels the unsaved-changes dialog.</code></p><p>验证状态应另写 <code>Validation is pending.</code>，不能写 <code>All tests pass.</code>。如果正文没有说明未保存内容是否还在，实际 Issue 要把这项加入检查，不把预期误写成观察结果。</p></details>`,22)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
